import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:hidden_volume/hidden_volume.dart' as hv;
import 'package:xveil/data/storage/hv_native.dart';
import 'package:xveil/data/storage/kv_log_store.dart';

// Generated by the core's log_hash_exact_read regression: an authenticated
// synthetic container, known password, honest record 7, wrong v2 hash for 8.
// Never open a running app's container or mutate the shared source fixture.
void main() {
  final fixture = Platform.environment['HV_LOG_HASH_FIXTURE'];
  final skip =
      fixture == null ||
      !(Platform.environment['XVEIL_HV_DYLIB']?.isNotEmpty ?? false);
  Future<hv.HvSpace> openFixture() async {
    expect(ensureHiddenVolumeLoaded(), isTrue);
    final directory = await Directory.systemTemp.createTemp('xv-log-hash-');
    addTearDown(() => directory.delete(recursive: true));
    final copy = await File(fixture!).copy('${directory.path}/fixture.hv');
    final space = hv.HvSpace.open(
      path: copy.path,
      password: Uint8List.fromList(utf8.encode('pw')),
    );
    addTearDown(space.close);
    expect(
      space.readLog(Ns.messageLog, 7),
      utf8.encode('seven'),
      reason: 'the fixture must open and its honest reference must be readable',
    );
    return space;
  }

  Matcher hashFailure(String kind) => isA<hv.HvException>()
      .having((e) => e.kind, 'kind', kind)
      .having((e) => e.message.toLowerCase(), 'message', contains('hash'));

  test(
    'exact FFI log read refuses a mismatching committed hash',
    () async {
      final space = await openFixture();
      expect(
        () => space.readLog(Ns.messageLog, 8),
        throwsA(hashFailure('Malformed')),
      );
      expect(space.readLog(Ns.messageLog, 7), utf8.encode('seven'));
    },
    skip: skip ? 'set verified HV library and synthetic hash fixture' : false,
  );

  test(
    'cached FFI log iteration checks the second reference too',
    () async {
      final space = await openFixture();
      expect(
        () => space.iterLogRange(
          namespace: Ns.messageLog,
          start: null,
          end: null,
          limit: 10,
        ),
        throwsA(hashFailure('Malformed')),
      );
    },
    skip: skip ? 'set verified HV library and synthetic hash fixture' : false,
  );

  test(
    'FFI integrity check refuses conflicting batch commitments',
    () async {
      final space = await openFixture();
      expect(space.verifyIntegrity, throwsA(hashFailure('IntegrityFailure')));
    },
    skip: skip ? 'set verified HV library and synthetic hash fixture' : false,
  );
}
